package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class SimpleType__narrow_TriageGen2Test {

    /**
     * Helper to access the protected _narrow method via reflection.
     */
    @SuppressWarnings("unchecked")
    private <T> T invokeNarrow(SimpleType type, Class<?> subclass) throws Exception {
        Method method = SimpleType.class.getDeclaredMethod("_narrow", Class.class);
        method.setAccessible(true);
        return (T) method.invoke(type, subclass);
    }

    @Test
    public void testNarrow_SameClass_ReturnsThis() throws Exception {
        SimpleType type = SimpleType.construct(String.class);

        // When subclass is the same as _class, it should return 'this' (identity)
        SimpleType result = invokeNarrow(type, String.class);

        assertSame("Should return the exact same instance when classes match", type, result);
    }

    @Test
    public void testNarrow_DifferentClass_ReturnsNewInstance() throws Exception {
        SimpleType type = SimpleType.construct(Object.class);

        // When subclass is different, it should return a new SimpleType instance
        SimpleType result = invokeNarrow(type, String.class);

        assertNotSame("Should return a new instance when classes differ", type, result);
        assertNotNull(result);

        // Verify the new instance has the correct class via toString or other means 
        // (Since we can't easily access protected fields, we rely on the logic provided in the snippet)
        assertTrue(result.toString().contains("java.lang.String"));
    }

    @Test
    public void testNarrow_SubclassRelationship_ReturnsNewInstance() throws Exception {
        // Even if it's a subclass, the logic says it creates a new instance 
        // because _class != subclass
        SimpleType type = SimpleType.construct(Number.class);

        SimpleType result = invokeNarrow(type, Integer.class);

        assertNotSame(type, result);
        assertTrue(result.toString().contains("java.lang.Integer"));
    }

    @Test
    public void testNarrow_UnrelatedClass_ReturnsNewInstance() throws Exception {
        // The code explicitly commented out the isAssignableFrom check.
        // Therefore, passing an unrelated class should NOT throw an exception,
        // but instead return a new SimpleType with that class.
        SimpleType type = SimpleType.construct(String.class);

        SimpleType result = invokeNarrow(type, Integer.class);

        assertNotSame(type, result);
        assertTrue(result.toString().contains("java.lang.Integer"));
    }

    @Test
    public void testNarrow_WithComplexState_PreservesAttributes() throws Exception {
        // Test that the new instance inherits attributes like bindings, handlers, etc.
        // We use withStaticTyping() and withValueHandler() to set up state.
        SimpleType type = SimpleType.construct(Object.class)
                .withStaticTyping()
                .withValueHandler(new Object());

        SimpleType result = invokeNarrow(type, String.class);

        assertNotSame(type, result);
        // Since we cannot easily access protected fields, we verify the behavior 
        // through the resulting object's properties if exposed, or simply ensure no crash.
        assertNotNull(result);
    }
}
